def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balance: dict[str, int] = {}
    frozen: set[str] = set()
    history: list[tuple] = []
    rejected: list[int] = []

    def parse_amount(token: str):
        if token and all("0" <= c <= "9" for c in token):
            return int(token)
        return None

    for index, op in enumerate(ops):
        parts = op.split(" ")
        verb = parts[0] if parts else ""
        ok = False

        if verb == "open" and len(parts) == 3:
            name, n = parts[1], parse_amount(parts[2])
            if n is not None and name not in balance:
                balance[name] = n
                history.append(("open", name))
                ok = True
        elif verb == "deposit" and len(parts) == 3:
            name, n = parts[1], parse_amount(parts[2])
            if n is not None and n > 0 and name in balance:
                balance[name] += n
                history.append(("deposit", name, n))
                ok = True
        elif verb == "withdraw" and len(parts) == 3:
            name, n = parts[1], parse_amount(parts[2])
            if (
                n is not None
                and n > 0
                and name in balance
                and name not in frozen
                and balance[name] >= n
            ):
                balance[name] -= n
                history.append(("withdraw", name, n))
                ok = True
        elif verb == "transfer" and len(parts) == 4:
            src, dst, n = parts[1], parts[2], parse_amount(parts[3])
            if (
                n is not None
                and n > 0
                and src != dst
                and src in balance
                and dst in balance
                and src not in frozen
                and balance[src] >= n
            ):
                balance[src] -= n
                balance[dst] += n
                history.append(("transfer", src, dst, n))
                ok = True
        elif verb == "freeze" and len(parts) == 2:
            name = parts[1]
            if name in balance and name not in frozen:
                frozen.add(name)
                history.append(("freeze", name))
                ok = True
        elif verb == "unfreeze" and len(parts) == 2:
            name = parts[1]
            if name in balance and name in frozen:
                frozen.remove(name)
                history.append(("unfreeze", name))
                ok = True
        elif verb == "undo" and len(parts) == 1 and history:
            action = history.pop()
            kind = action[0]
            if kind == "open":
                frozen.discard(action[1])
                del balance[action[1]]
            elif kind == "deposit":
                balance[action[1]] -= action[2]
            elif kind == "withdraw":
                balance[action[1]] += action[2]
            elif kind == "transfer":
                balance[action[1]] += action[3]
                balance[action[2]] -= action[3]
            elif kind == "freeze":
                frozen.remove(action[1])
            elif kind == "unfreeze":
                frozen.add(action[1])
            ok = True

        if not ok:
            rejected.append(index)

    return balance, rejected
